GOALS = {"Crescer inscritos":"Inscreva-se para receber a próxima parte.","Gerar conversas no WhatsApp":"O link para falar comigo está na descrição.","Divulgar link de afiliado":"O link recomendado está na descrição.","Vender produto ou serviço":"Veja os detalhes na descrição.","Levar para uma live":"Ative o lembrete para a próxima live.","Construir autoridade":"Siga o canal para mais conteúdos práticos."}
def packaging_options(topic, goal, destination=""):
    topic=topic or "este tema"; cta=GOALS[goal] + (f" {destination.strip()}" if destination.strip() else "")
    pairs=[(f"O erro que quase todos cometem em {topic}",f"Se você ainda ignora isto em {topic}, pode estar perdendo tempo."),(f"Antes de começar em {topic}, veja isto",f"Esta é a parte de {topic} que quase ninguém mostra."),(f"O que ninguém explica sobre {topic}",f"Em menos de um minuto, entenda o essencial sobre {topic}."),(f"3 pontos simples para entender {topic}",f"O maior erro em {topic} não é o que você imagina."),(f"O jeito mais inteligente de lidar com {topic}",f"Antes de decidir sobre {topic}, veja este ponto.")]
    return [{"title":t[:100],"hook":h,"cta":cta,"description":f"{h}\n\n{topic}\n\n{cta}\n\n#shorts #youtube"} for t,h in pairs]
